async function setDealerStatus(request:Request,env:Env,user:AuthUser,dealerId:string){const body:any=await request.json().catch(()=>({})),status=String(body.status||'').toUpperCase();if(!['APPROVED','SUSPENDED','REVOKED'].includes(status))return badRequest('Geçersiz bayi durumu.');const dealer=await one<any>(env.DB.prepare(`SELECT id,user_id,status FROM result_network_dealers WHERE id=?`).bind(dealerId));if(!dealer)return safeError(404,'DEALER_NOT_FOUND','Bayi bulunamadı.');const statements:D1PreparedStatement[]=[env.DB.prepare(`UPDATE result_network_dealers SET status=?,approved_by=CASE WHEN ?='APPROVED' THEN ? ELSE approved_by END,approved_at=CASE WHEN ?='APPROVED' THEN CURRENT_TIMESTAMP ELSE approved_at END,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(status,status,user.id,status,dealerId)];if(status!=='APPROVED')statements.push(env.DB.prepare(`UPDATE sessions SET revoked_at=CURRENT_TIMESTAMP WHERE user_id=? AND revoked_at IS NULL`).bind(dealer.user_id));await env.DB.batch(statements);await audit(env.DB,user.id,null,'RESULT_DEALER_STATUS_CHANGED','result_network_dealer',dealerId,{from:dealer.status,to:status,reason:body.reason||null});return json({ok:true,dealerId,status})}
async function removeDealerScope(env:Env,user:AuthUser,dealerId:string,scopeId:string){const scope=await one<any>(env.DB.prepare(`SELECT id FROM result_network_dealer_scopes WHERE id=? AND dealer_id=?`).bind(scopeId,dealerId));if(!scope)return safeError(404,'DEALER_SCOPE_NOT_FOUND','Bayi kapsamı bulunamadı.');await env.DB.prepare(`UPDATE result_network_dealer_scopes SET active=0 WHERE id=?`).bind(scopeId).run();await audit(env.DB,user.id,null,'RESULT_DEALER_SCOPE_REVOKED','result_network_dealer',dealerId,{scopeId});return json({ok:true,dealerId,scopeId,active:false})}
async function createNetworkInstitution(request:Request,env:Env,user:AuthUser){const body:any=await request.json().catch(()=>({})),code=String(body.mebCode||'').trim();const directory=code?await one<any>(env.DB.prepare(`SELECT meb_code,name,city,district FROM national_institution_directory WHERE meb_code=? AND status='ACTIVE'`).bind(code)):null;if(code&&!directory&&user.role!=='SUPER_ADMIN')return safeError(404,'DIRECTORY_INSTITUTION_NOT_FOUND','MEB referans kurum kaydı bulunamadı.');if(user.role!=='SUPER_ADMIN'&&!code)return badRequest('Bayi işlemi için MEB kurum kodu zorunludur.');const name=directory?.name||String(body.name||'').trim(),city=directory?.city||String(body.city||'').trim(),district=directory?.district||String(body.district||'').trim();if(!name||!city||!district)return badRequest('Kurum adı, il ve ilçe zorunludur.');const permission=await dealerCanAct(env,user,code);if(!permission.ok)return forbidden();const id=uuid('inst'),institutionCode=code||`ANX-${id.slice(-8).toUpperCase()}`;const existing=await one<any>(env.DB.prepare(`SELECT id FROM institutions WHERE code=?`).bind(institutionCode));if(existing)return safeError(409,'INSTITUTION_ALREADY_EXISTS','Bu kurum sistemde zaten açık.');await env.DB.batch([env.DB.prepare(`INSERT INTO institutions(id,name,code,city,district,status) VALUES(?,?,?,?,?,'ACTIVE')`).bind(id,name,institutionCode,city,district),env.DB.prepare(`INSERT INTO institution_access_controls(institution_id,lifecycle_status,updated_by) VALUES(?,'ACTIVE',?)`).bind(id,user.id),env.DB.prepare(`INSERT INTO institution_governance_events(id,institution_id,actor_user_id,actor_dealer_id,action,next_status,metadata_json) VALUES(?,?,?,?,'CREATE','ACTIVE',?)`).bind(uuid('ige'),id,user.id,permission.dealerId,JSON.stringify({mebCode:code||null}))]);await audit(env.DB,user.id,id,'RESULT_INSTITUTION_CREATED','institution',id,{mebCode:code||null,dealerId:permission.dealerId});return json({ok:true,institution:{id,name,code:institutionCode,city,district,status:'ACTIVE'}},201)}
async function setNetworkInstitutionStatus(request:Request,env:Env,user:AuthUser,id:string){const body:any=await request.json().catch(()=>({})),next=String(body.status||'').toUpperCase();if(!['ACTIVE','PASSIVE','FROZEN','ARCHIVED'].includes(next))return badRequest('Geçersiz kurum durumu.');const inst=await one<any>(env.DB.prepare(`SELECT i.*,COALESCE(iac.lifecycle_status,i.status) lifecycle_status FROM institutions i LEFT JOIN institution_access_controls iac ON iac.institution_id=i.id WHERE i.id=?`).bind(id));if(!inst)return safeError(404,'INSTITUTION_NOT_FOUND','Kurum bulunamadı.');const permission=await dealerCanAct(env,user,inst.code);if(!permission.ok)return forbidden();const legacy=next==='ACTIVE'?'ACTIVE':'PASSIVE',statements:D1PreparedStatement[]=[env.DB.prepare(`UPDATE institutions SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(legacy,id),env.DB.prepare(`INSERT INTO institution_access_controls(institution_id,lifecycle_status,reason,updated_by) VALUES(?,?,?,?) ON CONFLICT(institution_id) DO UPDATE SET lifecycle_status=excluded.lifecycle_status,reason=excluded.reason,updated_by=excluded.updated_by,updated_at=CURRENT_TIMESTAMP`).bind(id,next,body.reason||null,user.id),env.DB.prepare(`INSERT INTO institution_governance_events(id,institution_id,actor_user_id,actor_dealer_id,action,previous_status,next_status,metadata_json) VALUES(?,?,?,?,?,?,?,?)`).bind(uuid('ige'),id,user.id,permission.dealerId,next==='ARCHIVED'?'ARCHIVE':next==='FROZEN'?'FREEZE':next==='PASSIVE'?'PASSIVE':(inst.lifecycle_status==='FROZEN'?'UNFREEZE':'RESTORE'),inst.lifecycle_status,next,JSON.stringify({reason:body.reason||null}))];if(next!=='ACTIVE')statements.push(env.DB.prepare(`UPDATE sessions SET revoked_at=CURRENT_TIMESTAMP WHERE user_id IN (SELECT id FROM users WHERE institution_id=?) AND revoked_at IS NULL`).bind(id));await env.DB.batch(statements);await audit(env.DB,user.id,id,'RESULT_INSTITUTION_STATUS_CHANGED','institution',id,{from:inst.lifecycle_status,to:next,dealerId:permission.dealerId});return json({ok:true,id,status:next})}

export async function handleResultGovernanceMutation(request:Request,env:Env):Promise<Response|null>{
 const path=new URL(request.url).pathname;
 const dealerStatus=path.match(/^\/api\/admin\/result-network\/dealers\/([^/]+)\/status$/);
 const removeScope=path.match(/^\/api\/admin\/result-network\/dealers\/([^/]+)\/scopes\/([^/]+)$/);
 const finalize=path.match(/^\/api\/admin\/result-network\/administrations\/([^/]+)\/finalize$/);
 if(!dealerStatus&&!removeScope&&!finalize)return null;
 const user=await requireSuper(request,env);if(user instanceof Response)return user;
 if(dealerStatus&&request.method==='POST')return setDealerStatus(request,env,user,dealerStatus[1]);
 if(removeScope&&request.method==='DELETE')return removeDealerScope(env,user,removeScope[1],removeScope[2]);
 if(finalize&&request.method==='POST')return freezeAndPublishAdministration(request,env,user,finalize[1]);
 return safeError(405,'METHOD_NOT_ALLOWED','Bu yöntem desteklenmiyor.');
}

async function scopedOperatorInstitutions(env:Env,user:AuthUser,mode:string){
 if(user.role==='SUPER_ADMIN')return all<any>(env.DB.prepare(`SELECT i.id,i.name,i.code,i.city,i.district FROM institutions i LEFT JOIN institution_access_controls iac ON iac.institution_id=i.id WHERE COALESCE(iac.lifecycle_status,i.status)='ACTIVE' ORDER BY i.name LIMIT 2000`));
 if(mode!=='DEALER'&&user.role==='INSTITUTION_MANAGER'&&user.institution_id)return all<any>(env.DB.prepare(`SELECT i.id,i.name,i.code,i.city,i.district FROM institutions i LEFT JOIN institution_access_controls iac ON iac.institution_id=i.id WHERE i.id=? AND COALESCE(iac.lifecycle_status,i.status)='ACTIVE'`).bind(user.institution_id));
 return all<any>(env.DB.prepare(`SELECT DISTINCT i.id,i.name,i.code,i.city,i.district FROM institutions i LEFT JOIN institution_access_controls iac ON iac.institution_id=i.id LEFT JOIN national_institution_directory ndi ON ndi.meb_code=i.code JOIN result_network_dealers d ON d.user_id=? AND d.status='APPROVED' JOIN result_network_dealer_scopes s ON s.dealer_id=d.id AND s.active=1 WHERE COALESCE(iac.lifecycle_status,i.status)='ACTIVE' AND (s.scope_type='NATIONAL' OR (s.scope_type='INSTITUTION' AND s.meb_code=i.code) OR (s.scope_type='CITY' AND s.city=ndi.city) OR (s.scope_type='DISTRICT' AND s.city=ndi.city AND s.district=ndi.district)) ORDER BY i.name LIMIT 2000`).bind(user.id));
}

async function resultOperatorContext(request:Request,env:Env,institutionId:string):Promise<{user:AuthUser;effective:AuthUser;institution:any;dealerId:string|null}|Response>{
 const user=await getAuthUser(env,request);if(!user)return safeError(401,'UNAUTHENTICATED','Oturum açmanız gerekiyor.');
 const institution=await one<any>(env.DB.prepare(`SELECT i.id,i.name,i.code,COALESCE(iac.lifecycle_status,i.status) lifecycle_status FROM institutions i LEFT JOIN institution_access_controls iac ON iac.institution_id=i.id WHERE i.id=?`).bind(institutionId));
 if(!institution)return safeError(404,'INSTITUTION_NOT_FOUND','Kurum bulunamadı.');
 if(institution.lifecycle_status!=='ACTIVE')return safeError(409,'INSTITUTION_NOT_ACTIVE','Pasif, dondurulmuş veya arşivlenmiş kurumda değerlendirme yapılamaz.');
 const ownInstitution=user.role==='INSTITUTION_MANAGER'&&user.institution_id===institutionId;
 const dealerPermission=await dealerCanAct(env,user,institution.code);
 if(user.role!=='SUPER_ADMIN'&&!ownInstitution&&!dealerPermission.ok)return forbidden('Bu kurum için sonuç değerlendirme yetkiniz bulunmuyor.');
 const effective:AuthUser=user.role==='SUPER_ADMIN'||ownInstitution?user:{...user,role:'SUPER_ADMIN',institution_id:null};
 return{user,effective,institution,dealerId:dealerPermission.dealerId||null};
}

async function resultOperatorCatalog(request:Request,env:Env){
 const user=await getAuthUser(env,request);if(!user)return safeError(401,'UNAUTHENTICATED','Oturum açmanız gerekiyor.');
 const mode=new URL(request.url).searchParams.get('mode')==='DEALER'?'DEALER':'INSTITUTION';
 const institutions=await scopedOperatorInstitutions(env,user,mode);if(!institutions.length&&user.role!=='SUPER_ADMIN')return forbidden('Aktif kurum veya bayi kapsamınız bulunmuyor.');
 const [exams,opticals]=await Promise.all([
  all<any>(env.DB.prepare(`SELECT DISTINCT e.id,e.title,e.exam_type,e.academic_year,e.grade_level,e.publisher_name,srv.verified scoring_verified FROM exams e JOIN exam_channel_publications ecp ON ecp.exam_id=e.id AND ecp.channel='RESULT_NETWORK' AND ecp.status='ACTIVE' JOIN scoring_rule_versions srv ON srv.id=e.scoring_rule_version_id AND srv.verified=1 WHERE e.status IN ('ACTIVE','CLOSED') ORDER BY e.academic_year DESC,e.title LIMIT 500`)),
  all<any>(env.DB.prepare(`SELECT v.id,t.name,v.version FROM optical_template_versions v JOIN optical_templates t ON t.id=v.template_id WHERE v.active=1 AND t.active=1 AND v.parser_definition IS NOT NULL ORDER BY t.name,v.version DESC LIMIT 200`)),
 ]);
 return json({ok:true,institutions,exams,opticals});
}

async function batchOperatorContext(request:Request,env:Env,batchId:string){
 const batch=await one<any>(env.DB.prepare(`SELECT id,exam_id,institution_id,status FROM scan_batches WHERE id=?`).bind(batchId));
 if(!batch)return safeError(404,'BATCH_NOT_FOUND','Değerlendirme grubu bulunamadı.');
 const context=await resultOperatorContext(request,env,batch.institution_id);if(context instanceof Response)return context;return{...context,batch};
}

async function generateBatchAccessCodes(request:Request,env:Env,batchId:string){
 const context=await batchOperatorContext(request,env,batchId);if(context instanceof Response)return context;
 if(context.batch.status!=='COMMITTED')return badRequest('Önce değerlendirmeyi tamamlayın.','BATCH_NOT_COMMITTED');
 const administration=await one<any>(env.DB.prepare(`SELECT ea.*,e.academic_year FROM exam_administrations ea JOIN exams e ON e.id=ea.exam_id WHERE ea.exam_id=? AND ea.channel='RESULT_NETWORK' AND ea.status IN ('UPLOADING','READY','PUBLISHED') ORDER BY ea.created_at DESC LIMIT 1`).bind(context.batch.exam_id));
 if(!administration)return safeError(409,'RESULT_ADMINISTRATION_NOT_OPEN','Sınav önce Süper Admin tarafından Sonuç Ağı değerlendirmesine açılmalıdır.');
 const institution=await one<any>(env.DB.prepare(`SELECT i.id,i.code,i.name,i.city,i.district,ndi.meb_code FROM institutions i LEFT JOIN national_institution_directory ndi ON ndi.meb_code=i.code AND ndi.status='ACTIVE' WHERE i.id=?`).bind(context.batch.institution_id));
 if(!institution?.meb_code)return safeError(409,'OFFICIAL_INSTITUTION_CODE_REQUIRED','Öğrenci sonuç erişimi için kurum doğrulanmış MEB koduyla açılmalıdır.');
 await env.DB.prepare(`INSERT INTO result_network_institutions(id,administration_id,meb_code,licensed_institution_id,dealer_id,display_name_snapshot,city_snapshot,district_snapshot) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(administration_id,meb_code) DO UPDATE SET licensed_institution_id=excluded.licensed_institution_id,dealer_id=COALESCE(excluded.dealer_id,result_network_institutions.dealer_id),display_name_snapshot=excluded.display_name_snapshot,city_snapshot=excluded.city_snapshot,district_snapshot=excluded.district_snapshot`).bind(uuid('rni'),administration.id,institution.meb_code,institution.id,context.dealerId,institution.name,institution.city,institution.district).run();
 const resultInstitution=await one<any>(env.DB.prepare(`SELECT id FROM result_network_institutions WHERE administration_id=? AND meb_code=?`).bind(administration.id,institution.meb_code));
 const cursor=new URL(request.url).searchParams.get('cursor')||'';
 const candidates=await all<any>(env.DB.prepare(`SELECT ep.id participant_id,ep.student_number_snapshot,ep.name_snapshot,COALESCE(se.grade_level,e.grade_level) grade_level FROM exam_participants ep JOIN exam_results er ON er.participant_id=ep.id JOIN exams e ON e.id=ep.exam_id LEFT JOIN student_enrollments se ON se.student_id=ep.student_id AND se.institution_id=ep.institution_id AND se.status='ACTIVE' LEFT JOIN result_access_identities rai ON rai.administration_id=? AND rai.participant_id=ep.id WHERE ep.exam_id=? AND ep.institution_id=? AND ep.id>? AND rai.id IS NULL AND ep.student_number_snapshot IS NOT NULL AND trim(ep.student_number_snapshot)<>'' ORDER BY ep.id LIMIT 501`).bind(administration.id,context.batch.exam_id,context.batch.institution_id,cursor));
 const page=candidates.slice(0,500),codes:any[]=[];const academicEnd=Number(String(administration.academic_year).slice(0,4))+1,defaultDue=new Date(`${academicEnd}-09-30T23:59:59.000Z`),published=administration.published_at?new Date(new Date(administration.published_at).getTime()+90*86400000):defaultDue,expires=(published>defaultDue?published:defaultDue).toISOString();
 const statements:D1PreparedStatement[]=[];
 for(const participant of page){const code=secureResultCode(),password=await hashResultCode(env,code),studentNumber=normalizeLookup(participant.student_number_snapshot),identityId=uuid('rai');statements.push(env.DB.prepare(`INSERT INTO result_access_identities(id,administration_id,result_institution_id,participant_id,grade_level,normalized_name,student_number_lookup_token,access_code_hash,access_code_salt,expires_at) VALUES(?,?,?,?,?,?,?,?,?,?)`).bind(identityId,administration.id,resultInstitution.id,participant.participant_id,participant.grade_level,normalizeName(participant.name_snapshot),await hmac(env,`STUDENT_NUMBER|${institution.meb_code}|${studentNumber}`),password.hash,password.salt,expires));codes.push({studentNumber:participant.student_number_snapshot,fullName:participant.name_snapshot,gradeLevel:participant.grade_level,accessCode:code,expiresAt:expires})}
 for(let i=0;i<statements.length;i+=80)await env.DB.batch(statements.slice(i,i+80));
 const nextCursor=candidates.length>500?page[page.length-1]?.participant_id:null;await audit(env.DB,context.user.id,context.batch.institution_id,'RESULT_ACCESS_BATCH_ISSUED','scan_batch',batchId,{administrationId:administration.id,count:codes.length,hasMore:!!nextCursor});return json({ok:true,codes,nextCursor,administrationId:administration.id,oneTimeDisplay:true});
}

async function batchResultReport(request:Request,env:Env,batchId:string){
 const context=await batchOperatorContext(request,env,batchId);if(context instanceof Response)return context;
 if(context.batch.status!=='COMMITTED')return badRequest('Önce değerlendirmeyi tamamlayın.','BATCH_NOT_COMMITTED');
 const administration=await one<any>(env.DB.prepare(`SELECT id,status,ranking_frozen_at,participant_count,institution_count FROM exam_administrations WHERE exam_id=? AND channel='RESULT_NETWORK' ORDER BY created_at DESC LIMIT 1`).bind(context.batch.exam_id));
 const rows=await all<any>(env.DB.prepare(`WITH live AS MATERIALIZED (SELECT ep.id participant_id,ep.student_number_snapshot,ep.name_snapshot,ep.class_snapshot,COALESCE(se.grade_level,e.grade_level) grade_level,er.correct_count,er.wrong_count,er.blank_count,er.net,er.score,er.success_percent,er.institution_rank,COUNT(*) OVER(PARTITION BY ep.institution_id) live_institution_count,RANK() OVER(PARTITION BY ep.institution_id,COALESCE(ep.class_snapshot,'') ORDER BY COALESCE(er.score,er.net) DESC,er.correct_count DESC) live_class_rank,COUNT(*) OVER(PARTITION BY ep.institution_id,COALESCE(ep.class_snapshot,'')) live_class_count FROM exam_participants ep JOIN exam_results er ON er.participant_id=ep.id JOIN exams e ON e.id=ep.exam_id LEFT JOIN student_enrollments se ON se.student_id=ep.student_id AND se.institution_id=ep.institution_id AND se.status='ACTIVE' WHERE ep.exam_id=?), latest AS (SELECT MAX(snapshot_version) version FROM exam_result_snapshots WHERE exam_id=?) SELECT live.*,COALESCE(s.institution_rank,live.institution_rank) institution_rank,COALESCE(s.institution_count,live.live_institution_count) institution_count,COALESCE(s.class_rank,live.live_class_rank) class_rank,COALESCE(s.class_count,live.live_class_count) class_count,s.grade_rank,s.grade_count,s.district_rank,s.district_count,s.city_rank,s.city_count,s.network_rank,s.network_count,s.national_rank,s.national_count FROM live CROSS JOIN latest LEFT JOIN exam_result_snapshots s ON s.participant_id=live.participant_id AND s.snapshot_version=latest.version JOIN exam_participants ep ON ep.id=live.participant_id WHERE ep.institution_id=? ORDER BY live.net DESC,live.correct_count DESC,live.name_snapshot LIMIT 20000`).bind(context.batch.exam_id,context.batch.exam_id,context.batch.institution_id));
 return json({ok:true,publication:{status:administration?.status||'NOT_OPEN',rankingFrozenAt:administration?.ranking_frozen_at||null,participantCount:Number(administration?.participant_count||0),institutionCount:Number(administration?.institution_count||0)},rows});
}

export async function handleResultOperations(request:Request,env:Env):Promise<Response|null>{
 const path=new URL(request.url).pathname;
 if(path==='/api/admin/result-network/operations/catalog'&&request.method==='GET')return resultOperatorCatalog(request,env);
 const preview=path.match(/^\/api\/admin\/result-network\/operations\/exams\/([^/]+)\/preview-file$/);
 if(preview&&request.method==='POST'){
  const form=await request.clone().formData(),institutionId=String(form.get('institutionId')||'');
  if(!institutionId)return badRequest('Kurum seçilmelidir.');
  const published=await one<any>(env.DB.prepare(`SELECT 1 ok FROM exam_channel_publications WHERE exam_id=? AND channel='RESULT_NETWORK' AND status='ACTIVE'`).bind(preview[1]));
  if(!published)return safeError(404,'RESULT_EXAM_NOT_PUBLISHED','Sınav Sonuç Ağı kataloğunda yayınlanmamış.');
  const context=await resultOperatorContext(request,env,institutionId);if(context instanceof Response)return context;
  return previewExamFile(request,env,context.effective,preview[1]);
 }
 const resolve=path.match(/^\/api\/admin\/result-network\/operations\/scan-batches\/([^/]+)\/records\/([^/]+)\/resolve$/);
 if(resolve&&request.method==='POST'){const context=await batchOperatorContext(request,env,resolve[1]);if(context instanceof Response)return context;return resolveScanRecord(request,env,context.effective,resolve[1],resolve[2])}
 const evaluate=path.match(/^\/api\/admin\/result-network\/operations\/scan-batches\/([^/]+)\/evaluate$/);
 if(evaluate&&request.method==='POST'){const context=await batchOperatorContext(request,env,evaluate[1]);if(context instanceof Response)return context;return evaluateBatch(env,context.effective,evaluate[1])}
 const access=path.match(/^\/api\/admin\/result-network\/operations\/scan-batches\/([^/]+)\/access-codes$/);
 if(access&&request.method==='POST')return generateBatchAccessCodes(request,env,access[1]);
 const report=path.match(/^\/api\/admin\/result-network\/operations\/scan-batches\/([^/]+)\/report$/);
 if(report&&request.method==='GET')return batchResultReport(request,env,report[1]);
 const batch=path.match(/^\/api\/admin\/result-network\/operations\/scan-batches\/([^/]+)$/);
 if(batch&&request.method==='GET'){const context=await batchOperatorContext(request,env,batch[1]);if(context instanceof Response)return context;return getScanBatch(env,context.effective,batch[1])}
 return null;
}
export async function purgeExpiredResultNetwork(env:Env){
 for(const notice of [{type:'NOTICE_90',days:90},{type:'NOTICE_60',days:60},{type:'NOTICE_15',days:15}] as const){await env.DB.prepare(`INSERT INTO result_retention_events(id,administration_id,event_type,summary_json) SELECT 'rre_'||lower(hex(randomblob(16))),ea.id,?,json_object('retentionDueAt',ea.retention_due_at,'daysRemaining',?) FROM exam_administrations ea WHERE ea.channel='RESULT_NETWORK' AND ea.status IN ('PUBLISHED','ARCHIVED') AND ea.retention_due_at IS NOT NULL AND datetime(ea.retention_due_at,?||' days')<=CURRENT_TIMESTAMP AND NOT EXISTS(SELECT 1 FROM result_retention_events re WHERE re.administration_id=ea.id AND re.event_type=?)`).bind(notice.type,notice.days,String(-notice.days),notice.type).run()}
 const rows=await all<any>(env.DB.prepare(`SELECT id,exam_id FROM exam_administrations WHERE channel='RESULT_NETWORK' AND status IN ('PUBLISHED','ARCHIVED') AND retention_due_at IS NOT NULL AND retention_due_at<=CURRENT_TIMESTAMP LIMIT 5`));
 for(const row of rows){
  const participants=await all<{participant_id:string}>(env.DB.prepare(`SELECT DISTINCT ep.id participant_id FROM exam_participants ep JOIN result_network_institutions rni ON rni.administration_id=? AND (rni.licensed_institution_id=ep.institution_id OR rni.meb_code=(SELECT code FROM institutions WHERE id=ep.institution_id)) WHERE ep.exam_id=?`).bind(row.id,row.exam_id));
  await env.DB.prepare(`INSERT INTO result_retention_events(id,administration_id,event_type) VALUES(?,?,'PURGE_STARTED')`).bind(uuid('rre'),row.id).run();
  for(let i=0;i<participants.length;i+=80){const ids=participants.slice(i,i+80).map(x=>x.participant_id);if(ids.length)await env.DB.prepare(`DELETE FROM exam_participants WHERE id IN (${ids.map(()=>'?').join(',')})`).bind(...ids).run()}
  await env.DB.batch([env.DB.prepare(`DELETE FROM result_network_institutions WHERE administration_id=?`).bind(row.id),env.DB.prepare(`UPDATE exam_administrations SET status='PURGED' WHERE id=?`).bind(row.id),env.DB.prepare(`INSERT INTO result_retention_events(id,administration_id,event_type,summary_json) VALUES(?,?,'PURGE_COMPLETED',?)`).bind(uuid('rre'),row.id,JSON.stringify({participants:participants.length,examDefinitionRetained:true,answerKeysRetained:true,outcomesRetained:true,videosRetained:true}))]);
 }
}

export async function handleResultNetworkRequest(request:Request,env:Env):Promise<Response|null>{const url=new URL(request.url),p=url.pathname;if(p==='/api/public/results/config'&&request.method==='GET')return publicConfig(env);if(p==='/api/public/results/institutions'&&request.method==='GET')return searchInstitutions(env,url);if(p==='/api/public/results/lookup'&&request.method==='POST')return lookup(request,env);if(p==='/api/public/results/verify'&&request.method==='POST')return verify(request,env);if(p==='/api/public/results/student'&&request.method==='GET')return studentResults(request,env);const detail=p.match(/^\/api\/public\/results\/exams\/([^/]+)$/);if(detail&&request.method==='GET')return examDetail(request,env,detail[1]);if(p==='/api/admin/result-network/access-profile'&&request.method==='GET')return operatorAccessProfile(request,env);if(p==='/api/admin/result-network/portal-settings'&&request.method==='GET'){const user=await requireSuper(request,env);if(user instanceof Response)return user;return json({ok:true,copy:await portalCopy(env)})}if(p==='/api/admin/result-network/portal-settings'&&request.method==='PATCH'){const user=await requireSuper(request,env);if(user instanceof Response)return user;return updatePortalCopy(request,env,user)}if(p==='/api/admin/institution-directory/import'&&request.method==='POST'){const user=await requireSuper(request,env);if(user instanceof Response)return user;return importInstitutionDirectory(request,env,user)}if(p==='/api/admin/result-network/administrations'&&request.method==='GET'){const user=await requireSuper(request,env);if(user instanceof Response)return user;return listAdministrations(env)}if(p==='/api/admin/result-network/administrations'&&request.method==='POST'){const user=await requireSuper(request,env);if(user instanceof Response)return user;return createAdministration(request,env,user)}const publish=p.match(/^\/api\/admin\/result-network\/administrations\/([^/]+)\/publish$/);if(publish&&request.method==='POST'){const user=await requireSuper(request,env);if(user instanceof Response)return user;return publishAdministration(request,env,user,publish[1])}if(p==='/api/admin/result-network/access'&&request.method==='POST'){const user=await requireSuper(request,env);if(user instanceof Response)return user;return issueAccess(request,env,user)}if(p.match(/^\/api\/admin\/result-network\/users\/([^/]+)\/permission-profile$/)&&request.method==='POST'){const user=await requireSuper(request,env);if(user instanceof Response)return user;return assignPermissionProfile(request,env,user,p.match(/^\/api\/admin\/result-network\/users\/([^/]+)\/permission-profile$/)![1])}if(p==='/api/admin/result-network/governance'&&request.method==='GET'){const user=await requireSuper(request,env);if(user instanceof Response)return user;return governanceSnapshot(env)}if(p==='/api/admin/result-network/dealers'&&request.method==='POST'){const user=await requireSuper(request,env);if(user instanceof Response)return user;return createDealer(request,env,user)}const scope=p.match(/^\/api\/admin\/result-network\/dealers\/([^/]+)\/scopes$/);if(scope&&request.method==='POST'){const user=await requireSuper(request,env);if(user instanceof Response)return user;return setDealerScope(request,env,user,scope[1])}if(p==='/api/admin/result-network/institutions'&&request.method==='POST'){const user=await getAuthUser(env,request);if(!user)return safeError(401,'UNAUTHENTICATED','Oturum açmanız gerekiyor.');return createNetworkInstitution(request,env,user)}const lifecycle=p.match(/^\/api\/admin\/result-network\/institutions\/([^/]+)\/status$/);if(lifecycle&&request.method==='POST'){const user=await getAuthUser(env,request);if(!user)return safeError(401,'UNAUTHENTICATED','Oturum açmanız gerekiyor.');return setNetworkInstitutionStatus(request,env,user,lifecycle[1])}return null}
